const {chromium}=require('playwright');
const fs=require('fs');
const assert=require('node:assert/strict');
(async()=>{
 const browser=await chromium.launch({headless:true});
 const page=await browser.newPage({viewport:{width:1920,height:1080}});
 page.on('pageerror',e=>console.error('PAGE',e));
 await page.setContent('<style>.header{position:absolute;top:120px;left:500px;width:800px;height:65px}.bag-tab{display:inline-block;width:150px;height:45px}</style><div class="header"><div class="bag-tabs"><div class="bag-tab active" data-hb-owner="101">冰箱</div><div class="bag-tab" data-hb-owner="202">冰箱</div></div></div>');
 await page.evaluate(()=>{window.HOME_PAGE='BackpackUI';window.sent=[];window.addEventListener('message',e=>{if(e.data.sourcePageId)window.sent.push(e.data)});});
 await page.addScriptTag({content:fs.readFileSync(require('path').join(__dirname,'InlineEditor.js'),'utf8')});
 const cat={page:'BackpackUI',session:'s1',editable:true,sort:'rank',containers:[{owner:'101',original:'冰箱',name:'食材',rank:1},{owner:'202',original:'冰箱',name:'饮料',rank:2}]};
 async function publish(c=cat){await page.evaluate(d=>window.postMessage({type:'HOME_CATALOG',data:d},'*'),c);await page.waitForTimeout(250);}
 await publish();
 assert.equal(await page.locator('.hi-name').inputValue(),'食材');
 await page.locator('.hi-edit').click();
 await page.locator('.hi-name').fill('ad 冷冻食品');await page.locator('.hi-rank').fill('12');
 await page.locator('.hi-save').click();await page.waitForTimeout(30);
 let sent=await page.evaluate(()=>window.sent.filter(x=>x.type==='HOME_SAVE').at(-1));
 assert.deepEqual(sent.data.entries,[{owner:'101',name:'ad 冷冻食品',rank:12}]);assert.equal(sent.data.sort,'rank');
 cat.containers[0].name='ad 冷冻食品';cat.containers[0].rank=12;await publish();
 assert.equal(await page.locator('.hi-status').textContent(),'已保存');assert.equal(await page.locator('.hi-shield').count(),0);
 await page.evaluate(()=>{const t=document.querySelectorAll('.bag-tab');t[0].classList.remove('active');t[1].classList.add('active')});await page.waitForTimeout(250);
 assert.equal(await page.locator('.hi-name').inputValue(),'饮料');
 await page.locator('.hi-edit').click();await page.locator('.hi-rank').fill('1.5');await page.locator('.hi-save').click();
 assert.match(await page.locator('.hi-status').textContent(),/整数/);
 await page.locator('.hi-name').fill('不保存');await page.keyboard.press('Escape');await page.waitForTimeout(250);
 assert.equal(await page.locator('.hi-name').inputValue(),'饮料');
 await page.locator('.hi-edit').click();await page.locator('.hi-name').fill('');await page.locator('.hi-rank').fill('');await page.locator('.hi-save').click();await page.waitForTimeout(30);
 sent=await page.evaluate(()=>window.sent.filter(x=>x.type==='HOME_SAVE').at(-1));assert.deepEqual(sent.data.entries,[{owner:'202',name:'',rank:null}]);
 await page.evaluate(()=>window.postMessage({type:'HOME_ERROR',data:{page:'Backpack',message:'disk error'}},'*'));await page.waitForTimeout(250);
 assert.match(await page.locator('.hi-status').textContent(),/disk error/);assert.equal(await page.locator('.hi-save').isEnabled(),true);
 await publish({...cat,session:'s2'});assert.equal(await page.locator('.hi-shield').count(),0);
 await page.evaluate(()=>document.querySelectorAll('.bag-tab')[1].dataset.hbOwner='unknown');await page.waitForTimeout(250);assert.equal(await page.locator('.hb-inline').isHidden(),true);
 await page.evaluate(()=>{
   const panel=document.createElement('div');panel.className='bag-panel is-storage';panel.innerHTML='<div class="header"><div class="panel-title">双开门冰箱</div><span>分类标签</span></div>';document.body.appendChild(panel);
   window.postMessage({type:'WebUI_Backpack_InfoBMsg',data:{ownerId:202,backpackName:'双开门冰箱'}},'*');
 });await page.waitForTimeout(250);
 assert.equal(await page.locator('.is-storage .panel-title').textContent(),'[2] 饮料');
 await page.evaluate(()=>document.querySelector('.is-storage .panel-title').textContent='双开门冰箱');await page.waitForTimeout(250);
 assert.equal(await page.locator('.is-storage .panel-title').textContent(),'[2] 饮料');
 await page.evaluate(()=>window.postMessage({type:'WebUI_Backpack_InfoBMsg',data:{ownerId:303,backpackName:'陌生容器'}},'*'));await page.waitForTimeout(250);
 assert.equal(await page.locator('.is-storage .panel-title').textContent(),'陌生容器');
 await page.evaluate(()=>document.querySelectorAll('.bag-tab')[1].dataset.hbOwner='202');await page.waitForTimeout(250);
 await page.locator('.hi-edit').click();
 await page.locator('.hi-name').dispatchEvent('compositionstart');
 const count=await page.evaluate(()=>window.sent.filter(x=>x.type==='HOME_SAVE').length);
 await page.keyboard.press('Enter');await page.waitForTimeout(50);
 assert.equal(await page.evaluate(()=>window.sent.filter(x=>x.type==='HOME_SAVE').length),count);
 await page.locator('.hi-name').dispatchEvent('compositionend');await page.keyboard.press('Enter');await page.waitForTimeout(50);
 assert.equal(await page.evaluate(()=>window.sent.filter(x=>x.type==='HOME_SAVE').length),count);
 await page.locator('.hi-cancel').click();
 const late=await browser.newPage();
 await late.setContent('<div class="bag-panel is-storage"><div class="header"><div class="panel-title">冰箱</div></div></div>');
 await late.evaluate(()=>{window.HOME_PAGE='BackpackUI';window.__hbRightBag={ownerId:202,backpackName:'冰箱'};});
 await late.addScriptTag({content:fs.readFileSync(require('path').join(__dirname,'InlineEditor.js'),'utf8')});
 await late.evaluate(d=>window.postMessage({type:'HOME_CATALOG',data:d},'*'),cat);await late.waitForTimeout(250);
 assert.equal(await late.locator('.panel-title').textContent(),'[2] 饮料');
 assert.equal(await late.evaluate(()=>window.__hbRightBag.backpackName),'[2] 饮料');
 await late.evaluate(()=>{window.__hbRightBag.ownerId=101;window.__hbRightBag.backpackName='冰箱';document.querySelector('.panel-title').firstChild.nodeValue='原版刷新';});await late.waitForTimeout(250);
 assert.equal(await late.locator('.panel-title').textContent(),'[12] ad 冷冻食品');
 console.log('PASS: previous regression cases plus state received before script, no InfoB message, reactive title synchronization, right owner switching and text-node re-render.');
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
